UPDATE t_cd15_auto_schedule_record 
   SET DEL_FLAG = '1', 
       UPDATE_BY = #{createBy}, 
       UPDATE_TIME = #{createTime}
 WHERE schedule_date = #{scheduleDate}
   AND DEL_FLAG = '0'

