INSERT INTO T_CD15_SCHEDULE_RESULT (ID, schedule_DATE, CX_BATCH_NO, BATCH_NO, ORDER_NO, BIG_ROLL_CODE, MACHINE_ID, STEEL_STRIP_CODE1, STEEL_STRIP_CODE2, UNIT_CONSUME1, STOCK1_QTY1, STOCK1_QTY2, CUTTING_ANGLE, SUPPLY_TIME1, DAY_PLAN_QTY1, DAY_FINISH_QTY1, DAY_FINISH_RATE1, DAY_PRODUCE_ORDER1, DAY_SYS_ANALYSIS1, DAY_HAND_ANALYSIS1, NIGHT_PLAN_QTY1, NIGHT_FINISH_QTY1, NIGHT_FINISH_RATE1, NIGHT_PRODUCE_ORDER1, NIGHT_SYS_ANALYSIS1, NIGHT_HAND_ANALYSIS1, CX_CLASS1_PLAN, CX_CLASS2_PLAN, CX_CLASS3_PLAN, CX_CLASS4_PLAN, CX_CLASS5_PLAN, IS_RELEASE, PUBLISH_SUCCESS_COUNT, NEWEST_PUBLISH_TIME, MARK_CLOSE_OUT_TIP, PRODUCTION_STATUS, CLOSE_OUT_SPEC_FLAG, DATA_SOURCE, DEL_FLAG, CRAFT1, CRAFT2, EDGE_GLUE, REMARK, CREATE_BY, CREATE_TIME) SELECT SEQ_CD15_schedule.NEXTVAL AS ID, T.* FROM (
SELECT #{schedule.scheduleDate}, #{schedule.cxBatchNo,jdbcType = VARCHAR}, #{schedule.batchNo,jdbcType = VARCHAR}, #{schedule.orderNo,jdbcType = VARCHAR}, #{schedule.bigRollCode,jdbcType = VARCHAR}, #{schedule.machineId,jdbcType = VARCHAR}, #{schedule.steelStripCode1,jdbcType = VARCHAR}, #{schedule.steelStripCode2,jdbcType = VARCHAR}, #{schedule.unitConsume1,jdbcType = VARCHAR}, #{schedule.stock1Qty1,jdbcType = DOUBLE}, #{schedule.stock1Qty2,jdbcType = DOUBLE}, #{schedule.cuttingAngle,jdbcType = DOUBLE}, #{schedule.supplyTime1,jdbcType = DOUBLE}, #{schedule.dayPlanQty1,jdbcType = DOUBLE}, #{schedule.dayFinishQty1,jdbcType = DOUBLE}, #{schedule.dayFinishRate1,jdbcType = DOUBLE}, #{schedule.dayProduceOrder1,jdbcType = DOUBLE}, #{schedule.daySysAnalysis1,jdbcType = VARCHAR}, #{schedule.dayHandAnalysis1,jdbcType = VARCHAR}, #{schedule.nightPlanQty1,jdbcType = DOUBLE}, #{schedule.nightFinishQty1,jdbcType = DOUBLE}, #{schedule.nightFinishRate1,jdbcType = DOUBLE}, #{schedule.nightProduceOrder1,jdbcType = DOUBLE}, #{schedule.nightSysAnalysis1,jdbcType = VARCHAR}, #{schedule.nightHandAnalysis1,jdbcType = VARCHAR}, #{schedule.cxClass1Plan,jdbcType = DOUBLE}, #{schedule.cxClass2Plan,jdbcType = DOUBLE}, #{schedule.cxClass3Plan,jdbcType = DOUBLE}, #{schedule.cxClass4Plan,jdbcType = DOUBLE}, #{schedule.cxClass5Plan,jdbcType = DOUBLE}, #{schedule.isRelease,jdbcType = VARCHAR}, #{schedule.publishSuccessCount,jdbcType = INTEGER}, #{schedule.newestPublishTime,jdbcType = DATE}, #{schedule.markCloseOutTip,jdbcType = VARCHAR}, #{schedule.productionStatus,jdbcType = VARCHAR}, #{schedule.closeOutSpecFlag,jdbcType = VARCHAR}, #{schedule.dataSource,jdbcType = VARCHAR}, #{schedule.delFlag,jdbcType = VARCHAR}, #{schedule.craft1,jdbcType = VARCHAR}, #{schedule.craft2,jdbcType = VARCHAR}, #{schedule.edgeGlue,jdbcType = VARCHAR}, #{schedule.remark,jdbcType = VARCHAR}, #{schedule.createBy,jdbcType = VARCHAR}, #{schedule.createTime} FROM DUAL
) T

