MERGE INTO T_CD15_SCHEDULE_RESULT a USING (
SELECT #{schedule.scheduleDate} schedule_Date, #{schedule.cxBatchNo,jdbcType = VARCHAR} CX_BATCH_NO, #{schedule.batchNo,jdbcType = VARCHAR} BATCH_NO, #{schedule.orderNo,jdbcType = VARCHAR} order_No, #{schedule.bigRollCode,jdbcType = VARCHAR} big_Roll_Code, #{schedule.machineId,jdbcType = VARCHAR} machine_Id, #{schedule.steelStripCode1,jdbcType = VARCHAR} steel_Strip_Code1, #{schedule.steelStripCode2,jdbcType = VARCHAR} steel_Strip_Code2, #{schedule.unitConsume1,jdbcType = DOUBLE} unit_Consume1, #{schedule.stock1Qty1,jdbcType = DOUBLE} stock1_Qty1, #{schedule.stock1Qty2,jdbcType = DOUBLE} stock1_Qty2, #{schedule.cuttingAngle,jdbcType = DOUBLE} cutting_Angle, #{schedule.supplyTime1,jdbcType = DOUBLE} supply_Time1, #{schedule.dayPlanQty1,jdbcType = DOUBLE} day_Plan_Qty1, #{schedule.dayProduceOrder1,jdbcType = DOUBLE} day_Produce_Order1, #{schedule.dayHandAnalysis1,jdbcType = VARCHAR} day_Hand_Analysis1, #{schedule.nightPlanQty1,jdbcType = DOUBLE} night_Plan_Qty1, #{schedule.nightProduceOrder1,jdbcType = DOUBLE} night_Produce_Order1, #{schedule.nightHandAnalysis1,jdbcType = VARCHAR} night_Hand_Analysis1, #{schedule.cxClass1Plan,jdbcType = DOUBLE} CX_CLASS1_PLAN, #{schedule.cxClass2Plan,jdbcType = DOUBLE} CX_CLASS2_PLAN, #{schedule.cxClass3Plan,jdbcType = DOUBLE} CX_CLASS3_PLAN, #{schedule.cxClass4Plan,jdbcType = DOUBLE} CX_CLASS4_PLAN, #{schedule.cxClass5Plan,jdbcType = DOUBLE} CX_CLASS5_PLAN, #{schedule.isRelease,jdbcType = VARCHAR} is_Release, #{schedule.markCloseOutTip,jdbcType = VARCHAR} mark_Close_Out_Tip, #{schedule.craft1,jdbcType = VARCHAR} craft1, #{schedule.craft2,jdbcType = VARCHAR} craft2, #{schedule.edgeGlue,jdbcType = VARCHAR} edge_glue, #{schedule.remark,jdbcType = VARCHAR} remark, #{schedule.productionStatus,jdbcType = VARCHAR} production_Status, #{schedule.delFlag,jdbcType = VARCHAR} del_Flag, #{schedule.createBy,jdbcType = VARCHAR} create_By, #{schedule.createTime} create_Time, #{schedule.dataSource,jdbcType = VARCHAR} data_source from dual
) b ON (a.schedule_date = b.schedule_date AND a.big_Roll_Code = b.big_Roll_Code AND a.steel_Strip_Code1 = b.steel_Strip_Code1 and a.steel_Strip_Code2 = b.steel_Strip_Code2 AND a.machine_id = b.machine_id AND a.del_flag = '0' ) WHEN MATCHED THEN UPDATE SET a.stock1_Qty1 = b.stock1_Qty1, a.stock1_Qty2 = b.stock1_Qty2, a.day_Plan_Qty1 = b.day_Plan_Qty1, a.night_Plan_Qty1 = b.night_Plan_Qty1, a.day_Hand_Analysis1 = b.day_Hand_Analysis1, a.night_Hand_Analysis1 = b.night_Hand_Analysis1, a.mark_Close_Out_Tip = b.mark_Close_Out_Tip, a.supply_time1 = b.supply_time1, a.craft1 = b.craft1, a.craft2 = b.craft2, a.edge_glue = b.edge_glue, a.remark = b.remark, a.production_status = b.production_status, a.update_by = b.create_By, a.update_time = b.create_Time, a.data_source = b.data_source, a.CX_CLASS1_PLAN = b.CX_CLASS1_PLAN, a.CX_CLASS2_PLAN = b.CX_CLASS2_PLAN, a.CX_CLASS3_PLAN = b.CX_CLASS3_PLAN, a.CX_CLASS4_PLAN = b.CX_CLASS4_PLAN, a.CX_CLASS5_PLAN = b.CX_CLASS5_PLAN, a.day_Produce_Order1 = b.day_Produce_Order1, a.night_Produce_Order1 = b.night_Produce_Order1 WHEN NOT MATCHED THEN INSERT (a.id,a.schedule_Date,a.CX_BATCH_NO,a.batch_no,a.order_no,a.big_Roll_Code,a.machine_Id,a.steel_Strip_Code1,a.steel_Strip_Code2,a.unit_Consume1,a.supply_time1,a.stock1_Qty1,a.stock1_Qty2,a.cutting_Angle,a.day_Plan_Qty1,a.day_Produce_Order1,a.day_Hand_Analysis1,a.night_Plan_Qty1,a.night_Produce_Order1,a.night_Hand_Analysis1,a.is_release,a.mark_close_out_tip,a.remark,a.production_status,a.del_flag,a.create_by,a.create_time,a.data_source,a.CX_CLASS1_PLAN,a.CX_CLASS2_PLAN,a.CX_CLASS3_PLAN,a.CX_CLASS4_PLAN,a.CX_CLASS5_PLAN,a.craft1,a.craft2,a.edge_glue) values (SEQ_CD15_SCHEDULE.NEXTVAL,b.schedule_Date,b.CX_BATCH_NO,b.batch_no,b.order_no,b.big_Roll_Code,b.machine_Id,b.steel_Strip_Code1,b.steel_Strip_Code2,b.unit_Consume1,b.supply_time1,b.stock1_Qty1,b.stock1_Qty2,b.cutting_Angle,b.day_Plan_Qty1,b.day_Produce_Order1,b.day_Hand_Analysis1,b.night_Plan_Qty1,b.night_Produce_Order1,b.night_Hand_Analysis1,b.is_release,b.mark_close_out_tip,b.remark,b.production_status,b.del_flag,b.create_by,b.create_time,b.data_source,b.CX_CLASS1_PLAN,b.CX_CLASS2_PLAN,b.CX_CLASS3_PLAN,b.CX_CLASS4_PLAN,b.CX_CLASS5_PLAN,b.craft1,b.craft2,b.edge_glue)

MERGE INTO T_CD15_SCHEDULE_RESULT a USING (
SELECT #{schedule.dayPlanQty1,jdbcType = DOUBLE} day_Plan_Qty1, #{schedule.dayProduceOrder1,jdbcType = DOUBLE} day_Produce_Order1, #{schedule.nightPlanQty1,jdbcType = DOUBLE} night_Plan_Qty1, #{schedule.nightProduceOrder1,jdbcType = DOUBLE} night_Produce_Order1, #{schedule.isRelease,jdbcType = VARCHAR} is_Release, #{schedule.updateBy,jdbcType = VARCHAR} update_by, #{schedule.updateTime} update_time, #{schedule.id} id from dual
) b ON (a.id = b.id) WHEN MATCHED THEN UPDATE SET a.day_Plan_Qty1 = b.day_Plan_Qty1, a.day_Produce_Order1 = b.day_Produce_Order1, a.night_Plan_Qty1 = b.night_Plan_Qty1, a.night_Produce_Order1 = b.night_Produce_Order1, a.is_Release = b.is_Release, a.update_by = b.update_by, a.update_time = b.update_time

